const KEY = "(?:images|documents)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\.(?:jpg|png|webp|pdf)";

/** Keys are generated by the server ("images/<uuid>.png"); anything else is refused (this also rules out names like con.png). */
export const SAFE_KEY = new RegExp(`^${KEY}$`);

const KEY_AT_END_OF_PATH = new RegExp(`(?:^|/)(${KEY})$`);

/**
 * The storage key a stored URL points to, or null when it points to no file of ours. Works on the pathname alone, so a
 * pasted link with a query string, a different host spelling or an absolute localhost address still names the same file.
 * Used where a wrong "not the same file" answer would delete something still in use.
 */
export function storageKeyOf(url: string): string | null {
  let pathname: string;
  try {
    pathname = new URL(url, "https://placeholder.invalid").pathname;
  } catch {
    return null;
  }
  return KEY_AT_END_OF_PATH.exec(pathname)?.[1] ?? null;
}
